/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import java.util.Arrays;import page2020.util.EmptyUtil;import page2020.view.C3;import page2020.view.Content;import page2020.view.Element;import page2020.view.Tag;import page2020.view.bs4.B4show.AlignItems;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4show.P;import page2020.view.css3.C3color;public class B4box<T> extends Element<T, Content<?>> {	public static final class Size {		public static final String none = "0";		public static final String sm = "sm";		public static final String md = "md";		public static final String lg = "lg";		public static final String xl = "xl";	}	public static String sizeName(int number) {		switch (number) {		case 1:			return Size.sm;		case 2:			return Size.md;		case 3:			return Size.lg;		case 4:			return Size.xl;		default:			return null;		}	}	public B4box() {		super("div");	}	public B4box(String tagName) {		super(tagName);	}	public T top(String pixels) {		return super.css(C3.box.top(pixels));	}	public T right(String pixels) {		return super.css(C3.box.right(pixels));	}	public T bottom(String pixels) {		return super.css(C3.box.bottom(pixels));	}	public T left(String pixels) {		return super.css(C3.box.left(pixels));	}	public T width(String pixels) {		return super.css(C3.content.width(pixels));	}	public T height(String pixels) {		return super.css(C3.content.height(pixels));	}	public T w(int number) {		return super.cssClass(String.format("w-%d", 			(number == 25 || number == 50 || number == 75 || number == 100) ? number : 100));	}	public T h(int number) {		return super.cssClass(String.format("h-%d", 			(number == 25 || number == 50 || number == 75 || number == 100) ? number : 100));	}	public T mw() {		return super.cssClass("mw-100");	}	public T mh() {		return super.cssClass("mh-100");	}	public T p(int number) {		return super.cssClass("p-" + this.positive(number));	}	public T px(int number) {		return super.cssClass("px-" + this.positive(number));	}	public T py(int number) {		return super.cssClass("py-" + this.positive(number));	}	public T p(int x, int y) {		this.px(x);		this.py(y);		return super.bean();	}	public T pt(int number) {		return super.cssClass("pt-" + this.positive(number));	}	public T pr(int number) {		return super.cssClass("pr-" + this.positive(number));	}	public T pb(int number) {		return super.cssClass("pb-" + this.positive(number));	}	public T pl(int number) {		return super.cssClass("pl-" + this.positive(number));	}	public T border() {		return super.cssClass(B4border.border);	}	public T borderNone() {		return super.cssClass(B4border.none());	}	public T borderNone(String... sides) {		if (EmptyUtil.not(sides)) {			Arrays.asList(sides).forEach(side -> super.cssClass(B4border.none(side)));		} else {			this.borderNone();		}		return super.bean();	}	public T border(String borderColor) {		return super.cssClass(B4border.border, borderColor);	}	public T round() {		return super.cssClass(B4border.round);	}	public T round(String side) {		return super.cssClass(B4border.round(side));	}	public T roundSize(String size) {		return super.cssClass(B4border.roundSize(size));	}	public T circle() {		return super.cssClass(B4border.Round.circle);	}	public T shadow() {		return super.cssClass(B4border.shadow);	}	public T shadowSize(String size) {		return super.cssClass(B4border.shadow(size));	}	public T m(int number) {		return super.cssClass("m-" + this.number(number));	}	public T mx(int number) {		return super.cssClass("mx-" + this.number(number));	}	public T my(int number) {		return super.cssClass("my-" + this.number(number));	}	public T m(int x, int y) {		this.mx(x);		this.my(y);		return super.bean();	}	public T mt(int number) {		return super.cssClass("mt-" + this.number(number));	}	public T mr(int number) {		return super.cssClass("mr-" + this.number(number));	}	public T mb(int number) {		return super.cssClass("mb-" + this.number(number));	}	public T ml(int number) {		return super.cssClass("ml-" + this.number(number));	}	public T bg(String bg) {		if (bg.startsWith("bg-")) {			super.cssClass(bg);		} else {			super.css(C3.bg(bg));		}		return super.bean();	}	public T color(String color) {		if (color.startsWith("text-")) {			super.cssClass(color);		} else {			super.css(C3.color(color));		}		return super.bean();	}	public T transparent() {		super.css(C3.bg(C3color.transparent));		return super.bean();	}	public T show() {		super.removeClass(D.none);		return super.bean();	}	public T hide() {		super.cssClass(D.none);		return super.bean();	}	public T center(Tag<?> tag) {		super.cssClass(D.flex, AlignItems.center);		super.css(C3.height("100%"));		super.append((Content<?>) tag.cssClass(D.block, P.mxAuto));		return super.bean();	}	public T center() {		return super.cssClass(D.flex, AlignItems.center);	}	private String positive(int number) {		return String.valueOf((number >= 0 && number <= 5) ? number : 0);	}	private String number(int number) {		String value;		if (number >= 0 && number <= 5) {			value = String.valueOf(number);		} else if (number <= -1 && number >= -5) {			value = String.format("n%d", (-1) * number);		} else {			value = "0";		}		return value;	}}